        check("{3, 4}", 3.5, NumberAverager.averageOfParseable(new String[] {"3", "4"}));
        check("{a, b}", -1.0, NumberAverager.averageOfParseable(new String[] {"a", "b"}));
        check("empty array", -1.0, NumberAverager.averageOfParseable(new String[] {}));
        check("{-4, 4}", 0.0, NumberAverager.averageOfParseable(new String[] {"-4", "4"}));
        check("{7}", 7.0, NumberAverager.averageOfParseable(new String[] {"7"}));
        check("{2, 4, banana, 6, 8}", 5.0, NumberAverager.averageOfParseable(new String[] {"2", "4", "banana", "6", "8"}));
