public class NumberAverager {

    public static double averageOfParseable(String[] tokens) {
        int sum = 0;
        int count = 0;
        for (String t : tokens) {
            try {
                sum += Integer.parseInt(t);
                count++;
            } catch (NumberFormatException e) {
                // not a number -- skip it
            }
        }
        if (count == 0) {
            return -1.0;
        }
        return (double) sum / count;
    }
}
